using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class LanguagesPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Languages", "View"); return AdminDataService.GetList("Languages"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Languages", "View"); return AdminDataService.GetDefinitionMetadata("Languages"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Languages", "Delete"); return AdminDataService.Delete("Languages", id); } } }
